import React from 'react';

import { Link } from 'react-router-dom';

import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { declOfNum } from '@helpers/formatHelper';
import PohAva from '@ui-kit/Ava';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import Empty from '@ui-kit/Empty';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

import { AuthContext } from '../../../contexts/AuthContext';
import { getOneFriendData } from '../@services/user.services';
import { IOneFriend } from '../@types/user.types';
import HikingListTogether from '../components/HikingListTogether';
import UserObstacles from '../components/UserObstacles';
import UserPositions from '../components/UserPositions';

interface IOneUserPageProps {
  id_user: number;
}

const OneUserPage: React.FC<IOneUserPageProps> = ({ id_user }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [friend, setFriend] = React.useState<IOneFriend | null>(null);

  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);
        const fr = await getOneFriendData(id_user);
        setFriend(fr);
      } finally {
        setIsLoading(false);
      }
    };
    start();
  }, [id_user]);

  const authContext = React.useContext(AuthContext);

  if (isLoading) return <PageLoader />;
  if (!friend)
    return <Empty>Данные недоступны. Может быть вы еще не были в совместных походах?</Empty>;

  return (
    <section>
      <PohBreadcrumbs
        data={[
          { href: '/users', text: 'Походники' },
          { href: `/user/${id_user}`, text: [friend.name, friend.surname].join(' '), active: true },
        ]}
      />
      <PohContainer>
        <PageHeader
          title={
            <>
              <div>{[friend?.name, friend?.surname].join(' ')}</div>
              <div style={{ fontSize: 12 }} className="text-muted">
                {friend.statistic && (
                  <>
                    <div>
                      Вы{' '}
                      {authContext.user?.id === id_user
                        ? `были в ${friend.statistic.hikingCount} `
                        : `и ${friend.name} были в ${friend.statistic.hikingCount} ${declOfNum(friend.statistic.hikingCount, ['совместном', 'совместных', 'совместных'])} `}
                      {declOfNum(friend.statistic.hikingCount, ['походе', 'походах', 'походах'])}
                    </div>
                    <div>
                      Ваш первый зарегистрированный поход состоялся{' '}
                      {friend.statistic.hikingFirstDate.toLocaleDateString()}, а крайний{' '}
                      {friend.statistic.hikingLastDate.toLocaleDateString()}
                    </div>
                  </>
                )}
                <div>
                  Статистика за{' '}
                  <Link to={`/user/${id_user}/stat/${new Date().getFullYear()}`}>
                    {new Date().getFullYear()}
                  </Link>{' '}
                  год
                </div>
              </div>
            </>
          }
        >
          <PohAva src={friend.photo} width={100} />
        </PageHeader>

        <PohRow>
          <PohCol sm={6}>
            <h4>{authContext.user?.id === id_user ? 'Мои' : 'Совместные'} походы</h4>
            <HikingListTogether id_user={id_user} />
          </PohCol>
          <PohCol sm={6}>
            <UserObstacles id_user={id_user} />
            <UserPositions id_user={id_user} />
          </PohCol>
        </PohRow>
      </PohContainer>
    </section>
  );
};

export default OneUserPage;
