import React from 'react';

import { Link } from 'react-router-dom';

import { IObstacleForUser } from '@apps/Obstacles/@types/obstacles.types';

interface IUserObstaclesStatProps {
  obstacle: IObstacleForUser;
  label: React.ReactNode;
  children: React.ReactNode;
}

const UserObstaclesStat: React.FC<IUserObstaclesStatProps> = ({ obstacle, label, children }) => {
  return (
    <>
      <small className="text-muted d-block mt-n1">{label}</small>
      <h5 className="text-success d-block m-0">{children}</h5>
      <Link
        to={`/hiking/${obstacle.hiking.id}/obstacles/${obstacle.id}/${obstacle.id_hiking_obstacle}`}
      >
        {obstacle.name}
      </Link>
    </>
  );
};

export default UserObstaclesStat;
