import React from 'react';

import { IObstacleForUser } from '@apps/Obstacles/@types/obstacles.types';
import { formatAltitude } from '@helpers/formatHelper';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import UserObstaclesStat from './UserObstaclesStat';

interface IUserObstaclesPeaksStatProps {
  obstacles: IObstacleForUser[];
}

const UserObstaclesPeaksStat: React.FC<IUserObstaclesPeaksStatProps> = ({ obstacles }) => {
  const [first, last, low, high] = React.useMemo(() => {
    let first1 = obstacles[0];
    let last1 = obstacles[0];
    let low1 = obstacles[0];
    let high1 = obstacles[0];

    obstacles.forEach((val) => {
      if (val.date_in < first1.date_in) first1 = val;
      if (val.date_out > last1.date_out) last1 = val;
      if (val.altitude < low1.altitude) low1 = val;
      if (val.altitude > high1.altitude) high1 = val;
    });

    return [first1, last1, low1, high1];
  }, [obstacles]);

  return (
    <PohRow>
      <PohCol sm="3">
        <UserObstaclesStat label="Самая первая" obstacle={first}>
          {first.date_in.toLocaleDateString()}
        </UserObstaclesStat>
      </PohCol>
      <PohCol sm="3">
        <UserObstaclesStat label="Самая недавняя" obstacle={last}>
          {last.date_out.toLocaleDateString()}
        </UserObstaclesStat>
      </PohCol>
      <PohCol sm="3">
        <UserObstaclesStat label="Самая высокая" obstacle={high}>
          {formatAltitude(high.altitude)}
        </UserObstaclesStat>
      </PohCol>
      <PohCol sm="3">
        <UserObstaclesStat label="Самая низкая" obstacle={low}>
          {formatAltitude(low.altitude)}
        </UserObstaclesStat>
      </PohCol>
    </PohRow>
  );
};

export default UserObstaclesPeaksStat;
